const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry Definition for Sakha Republic
  const sakha = ee.FeatureCollection('FAO/GAUL/2015/level1')
    .filter(ee.Filter.and(
      ee.Filter.eq('ADM0_NAME', 'Russian Federation'),
      ee.Filter.eq('ADM1_NAME', 'Sakha (Yakutiya) Republic')
    ))
    .first();

  if (!sakha) {
    console.log("Error: Could not find Sakha (Yakutiya) Republic in FAO/GAUL data.");
    console.log("D"); // Data/region name incorrect or not found
    return;
  }
  const geometry = sakha.geometry();

  // Define the years for comparison
  const year1 = 2015;
  const year2 = 2021;
  const scale = 500; // MODIS resolution is 500m

  // Function to get total burned area for a given year
  const getBurnedArea = (year) => {
    const startDate = ee.Date.fromYMD(year, 1, 1);
    const endDate = ee.Date.fromYMD(year, 12, 31);

    // Use MODIS MCD64A1 Burned Area Product (Collection 61)
    const burnedAreaCollection = ee.ImageCollection('MODIS/061/MCD64A1')
      .filterDate(startDate, endDate)
      .filterBounds(geometry);

    // Check if the collection is empty
    if (burnedAreaCollection.size().getInfo() === 0) {
      return {
        area: null,
        count: 0,
        empty: true
      };
    }

    // Select the 'BurnDate' band. Pixels with BurnDate > 0 indicate burned areas.
    // Convert BurnDate to a binary mask (1 for burned, 0 for unburned)
    // Then calculate the area of burned pixels.
    const burnedArea = burnedAreaCollection.map(image => {
      const burnMask = image.select('BurnDate').gt(0); // Binary mask for burned pixels
      return burnMask.multiply(ee.Image.pixelArea()).rename('burned_area');
    }).sum(); // Sum all monthly burned areas for the year

    // Calculate total burned area in square kilometers
    const stats = burnedArea.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: geometry,
      scale: scale,
      maxPixels: 1e12,
      crs: 'EPSG:4326', // Ensure consistent CRS
      crsTransform: [1, 0, 0, 0, 1, 0]
    });

    const totalAreaSqM = stats.get('burned_area').getInfo();
    const totalAreaSqKm = totalAreaSqM !== null ? totalAreaSqM / 1e6 : null;

    // Get pixel count of the burned area band (to check for C2 later if area is 0)
    const pixelCount = burnedArea.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: geometry,
      scale: scale,
      maxPixels: 1e12,
      crs: 'EPSG:4326',
      crsTransform: [1, 0, 0, 0, 1, 0]
    }).get('burned_area').getInfo();

    return {
      area: totalAreaSqKm,
      count: pixelCount,
      empty: false
    };
  };

  // Get burned area for 2015
  const result2015 = getBurnedArea(year1);
  if (result2015.empty) {
    console.log(`No images found for ${year1}.`);
    console.log("C1");
    return;
  }
  if (result2015.area === null) {
    console.log(`Calculation failed for ${year1}. Result is None.`);
    console.log("C3");
    return;
  }
  if (result2015.count === 0 && result2015.area === 0) {
    console.log(`No valid pixels with burn data for ${year1}.`);
    // C2 is for *after* masking, here it means no data *at all* for the region.
    // If pixelCount is 0, then the area will also be 0, which is a valid zero meaning no burn detected.
  }

  // Get burned area for 2021
  const result2021 = getBurnedArea(year2);
  if (result2021.empty) {
    console.log(`No images found for ${year2}.`);
    console.log("C1");
    return;
  }
  if (result2021.area === null) {
    console.log(`Calculation failed for ${year2}. Result is None.`);
    console.log("C3");
    return;
  }
  if (result2021.count === 0 && result2021.area === 0) {
    console.log(`No valid pixels with burn data for ${year2}.`);
    // Same as above.
  }

  const area2015 = result2015.area;
  const area2021 = result2021.area;

  console.log(`Burned area in ${year1} (sq km): ${area2015.toFixed(2)} (Pixels: ${result2015.count})`);
  console.log(`Burned area in ${year2} (sq km): ${area2021.toFixed(2)} (Pixels: ${result2021.count})`);

  if (area2015 > area2021) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
